using System.Globalization;
using System.Text;

namespace Creatura.Bench;

/// <summary>
/// A battery scored: the verdict of every hypothesis over the rows, rendered as markdown beside the battery's own
/// README. The README is hand-written and never overwritten by this; the report is a generated file next to it.
/// </summary>
public sealed record BatteryReport(Battery Battery, IReadOnlyList<Row> Rows, IReadOnlyDictionary<string, HypothesisVerdict> Verdicts)
{
    /// <summary>The first line of every file this writes; a file without it is somebody's and is left alone.</summary>
    public const string Marker = "<!-- generated by Creatura.Bench; the hand-written account is README.md -->";

    public static BatteryReport Score(Battery battery, IReadOnlyList<Row> rows) =>
        new(battery, rows, battery.Hypotheses.ToDictionary(h => h.Id, h => h.Judge(rows), StringComparer.Ordinal));

    public HypothesisVerdict this[string id] => Verdicts[id];

    public string ToMarkdown()
    {
        var inv = CultureInfo.InvariantCulture;
        var sb = new StringBuilder();
        sb.Append(Marker).Append('\n');
        sb.Append("# Battery ").Append(Battery.Id).Append('\n').Append('\n');
        sb.Append("Source: ").Append(Battery.Source).Append(". ").Append(Rows.Count.ToString(inv)).Append(" rows, ")
            .Append(Battery.Arms.Count.ToString(inv)).Append(" arms, ").Append(Battery.Repeats.ToString(inv)).Append(" repeats.\n\n");
        sb.Append("| id | hypothesis | verdict | finding |\n|---|---|---|---|\n");
        foreach (var h in Battery.Hypotheses)
        {
            var verdict = Verdicts.TryGetValue(h.Id, out var v) ? v : HypothesisVerdict.NotRun;
            sb.Append("| ").Append(h.Id).Append(" | ").Append(Cell(h.Statement)).Append(" | **").Append(Word(verdict)).Append("** | ").Append(Cell(h.Finding ?? "")).Append(" |\n");
        }

        if (Rows.Count > 0)
        {
            sb.Append("\n| arm | agent | rows | real | claimed | handed off | open | ticks |\n|---|---|---|---|---|---|---|---|\n");
            foreach (var g in Rows.GroupBy(r => (r.Arm, r.Agent)).OrderBy(g => g.Key.Arm, StringComparer.Ordinal).ThenBy(g => g.Key.Agent, StringComparer.Ordinal))
            {
                var n = g.Count();
                sb.Append("| ").Append(g.Key.Arm).Append(" | ").Append(g.Key.Agent).Append(" | ").Append(n.ToString(inv))
                    .Append(" | ").Append(g.Count(r => r.Outcome == OutcomeClass.Real).ToString(inv))
                    .Append(" | ").Append(g.Count(r => r.Outcome == OutcomeClass.Claimed).ToString(inv))
                    .Append(" | ").Append(g.Count(r => r.Outcome == OutcomeClass.HandedOff).ToString(inv))
                    .Append(" | ").Append(g.Count(r => r.Outcome == OutcomeClass.Open).ToString(inv))
                    .Append(" | ").Append(g.Average(r => r.Ticks).ToString("0.0", inv)).Append(" |\n");
            }
        }

        return sb.ToString();
    }

    /// <summary>The verdict as the markdown writes it: held, failed, mixed, not run.</summary>
    public static string Word(HypothesisVerdict verdict) => verdict switch
    {
        HypothesisVerdict.Held => "held",
        HypothesisVerdict.Failed => "failed",
        HypothesisVerdict.Mixed => "mixed",
        HypothesisVerdict.NotRun => "not run",
        _ => throw new ArgumentOutOfRangeException(nameof(verdict)),
    };

    /// <summary>
    /// Writes the markdown into the directory as <paramref name="fileName"/> (<c>report.md</c>) and returns the path written. A
    /// <c>README.md</c> is never the target, and a file that does not start with <see cref="Marker"/> is never overwritten: the
    /// report then goes to the next free numbered name (<c>report-2.md</c>, …).
    /// </summary>
    public string Write(string directory, string fileName = "report.md")
    {
        if (string.Equals(fileName, "README.md", StringComparison.OrdinalIgnoreCase))
            throw new ArgumentException("README.md is hand-written; a report goes beside it, never over it", nameof(fileName));
        Directory.CreateDirectory(directory);
        var path = Path.Combine(directory, fileName);
        var stem = Path.GetFileNameWithoutExtension(fileName);
        var ext = Path.GetExtension(fileName);
        for (var n = 2; !Ours(path); n++) path = Path.Combine(directory, $"{stem}-{n}{ext}");
        File.WriteAllText(path, ToMarkdown());
        return path;
    }

    private static bool Ours(string path)
    {
        if (!File.Exists(path)) return true;
        using var reader = new StreamReader(path);
        return reader.ReadLine() == Marker;
    }

    private static string Cell(string s) => s.Replace("|", "\\|").Replace("\n", " ");
}
